import React from 'react'
import ReactDOM from 'react-dom/client'
import App from './App.jsx'
import './index.css'
import axios from 'axios'

// Configure Axios to always send credentials (cookies) in cross-origin requests
axios.defaults.withCredentials = true;

// Intercept Axios requests to sanitize Authorization header.
// Since we now use secure HTTP-only cookies, we prune any legacy "Bearer null"
// or "Bearer undefined" headers generated by older localstorage references.
axios.interceptors.request.use((config) => {
  if (!config.headers) {
    config.headers = {};
  }
  const auth = config.headers.Authorization || config.headers.authorization;
  if (auth === 'Bearer null' || auth === 'Bearer undefined') {
    delete config.headers.Authorization;
    delete config.headers.authorization;
  }
  return config;
}, (error) => {
  return Promise.reject(error);
});

// Intercept Axios responses to auto-logout on authentication failures.
// If the backend cookie is invalid, expired, or missing, it returns an error
// response. We intercept it, clear the local user profile, and redirect to home page.
axios.interceptors.response.use((response) => {
  if (response.data && (response.data.error === 'Invalid token!' || response.data.error === 'Token not provided!')) {
    localStorage.removeItem('user');
    if (window.location.pathname !== '/') {
      window.location.href = '/';
    }
  }
  return response;
}, (error) => {
  return Promise.reject(error);
});

// Configure global Fetch to always send credentials (cookies) and sanitize Authorization header.
// Overriding window.fetch globally ensures that all AJAX calls across the frontend
// include 'credentials: include' automatically without refactoring dozens of files.
const originalFetch = window.fetch;
window.fetch = async (url, options = {}) => {
  // Ensure the browser transmits the HttpOnly session cookies (credentials) automatically
  options.credentials = options.credentials || 'include';
  
  if (!options.headers) {
    options.headers = {};
  }
  
  // Prune any legacy "Bearer null" or "Bearer undefined" authorization headers
  if (options.headers instanceof Headers) {
    const auth = options.headers.get('Authorization');
    if (auth === 'Bearer null' || auth === 'Bearer undefined') {
      options.headers.delete('Authorization');
    }
  } else if (typeof options.headers === 'object') {
    const auth = options.headers['Authorization'] || options.headers['authorization'];
    if (auth === 'Bearer null' || auth === 'Bearer undefined') {
      delete options.headers['Authorization'];
      delete options.headers['authorization'];
    }
  }
  
  const response = await originalFetch(url, options);
  
  // Intercept authentication errors (invalid/expired tokens) on global fetch responses to trigger logout
  const contentType = response.headers.get('content-type');
  if (contentType && contentType.includes('application/json')) {
    try {
      const clone = response.clone();
      const data = await clone.json();
      if (data && (data.error === 'Invalid token!' || data.error === 'Token not provided!')) {
        localStorage.removeItem('user');
        if (window.location.pathname !== '/') {
          window.location.href = '/';
        }
      }
    } catch (e) {
      // Ignore cloning/parsing failures
    }
  }
  
  return response;
};

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
)
